import math

def select_next_node(graph, unvisited_nodes):
    pre = graph.graph['precomputed']
    unvisited_set = set(unvisited_nodes)

    # Pre-extract clustering for all nodes to avoid repeated lookups
    clustering = {n: graph.nodes[n]['clustering'] for n in unvisited_nodes}
    degree = {n: graph.nodes[n]['degree'] for n in unvisited_nodes}

    def local_entropy(node):
        neighbors = [nbr for nbr in graph.neighbors(node) if nbr in unvisited_set]
        if not neighbors:
            return 0.0
        degs = [degree[nbr] for nbr in neighbors]
        total = sum(degs)
        if total == 0:
            return 0.0
        probs = [d / total for d in degs]
        ent = -sum(p * math.log(p, 2) if p > 0 else 0 for p in probs)
        return ent  # entropy in bits

    scores = {}
    for node in unvisited_nodes:
        neighbors = [nbr for nbr in graph.neighbors(node) if nbr in unvisited_set]
        if not neighbors:
            scores[node] = 0.0
            continue

        # Sum of degrees weighted by inverse clustering of neighbors (avoid div0)
        weighted_sum = 0.0
        for nbr in neighbors:
            c = clustering[nbr]
            weight = 1.0 / (c + 0.01)  # small smoothing to avoid div0
            weighted_sum += degree[nbr] * weight

        ent = local_entropy(node)

        # Combine weighted neighbor connectivity and entropy with a harmonic mean to balance both
        if weighted_sum + ent > 0:
            score = 2 * weighted_sum * ent / (weighted_sum + ent)
        else:
            score = 0.0

        scores[node] = score

    next_node = max(scores, key=scores.get)
    return next_node

def select_next_node(graph, unvisited_nodes):
    # Read precomputed global features
    degree_variance = graph.graph['precomputed']['degree_variance']
    apl_lcc = graph.graph['precomputed']['apl_lcc']

    nodes = unvisited_nodes
    # Extract node features
    betweenness = {n: graph.nodes[n]['betweenness'] for n in nodes}
    clustering = {n: graph.nodes[n]['clustering'] for n in nodes}
    degree = {n: graph.nodes[n]['degree'] for n in nodes}
    eigenvector = {n: graph.nodes[n]['eigenvector'] for n in nodes}

    # Normalize features to [0,1]
    def normalize(d):
        vals = list(d.values())
        min_v, max_v = min(vals), max(vals)
        if max_v - min_v < 1e-12:
            return {k:0 for k in d}
        return {k: (v - min_v)/(max_v - min_v) for k,v in d.items()}

    bet_n = normalize(betweenness)
    clust_n = normalize(clustering)
    deg_n = normalize(degree)
    eig_n = normalize(eigenvector)

    # Adaptive weights based on global degree variance and average path length
    w_deg = 0.5 * (degree_variance / (degree_variance + 1)) + 0.1
    w_clust = 0.4 * (apl_lcc / (apl_lcc + 1)) + 0.1
    # Inverse weighting for betweenness and eigenvector to diversify selection
    w_bet = 0.3 * (1 - min(1, bet_n[max(bet_n, key=bet_n.get)])) + 0.1
    w_eig = 0.3 * (1 - min(1, eig_n[max(eig_n, key=eig_n.get)])) + 0.1

    scores = {}
    for n in nodes:
        score = (
            w_deg * deg_n[n] + 
            w_clust * (1 - clust_n[n]) +
            w_bet * (1 - bet_n[n]) +
            w_eig * (1 - eig_n[n])
        )
        scores[n] = score

    next_node = max(scores, key=scores.get)
    return next_node
